    /// <summary> EditMode tests for the engine-free core. </summary>
    public class WFCCoreTests {
        // ---------------------------------------------------------------- masks
        [Test]
        public void BlobHas47DistinctSlots() {
            HashSet<int> seen = new();
            for (int m = 0; m < 256; m++) {
                seen.Add(OverlayMasks.Reduce(m));
            }

            Assert.AreEqual(OverlayMasks.BLOB_COUNT, seen.Count);
            for (int m = 0; m < 256; m++) {
                Assert.AreEqual(OverlayMasks.Reduce(m), OverlayMasks.BlobSlotMask(OverlayMasks.BlobIndex(m)), $"mask {m}");
            }

            Assert.AreEqual(0, OverlayMasks.BlobIndex(0));
            int corner = 0;
            for (int i = 0; i < OverlayMasks.BLOB_COUNT; i++) {
                if (!OverlayMasks.IsCornerSlot(i)) continue;
                corner++;
            }

            Assert.AreEqual(31, corner);
        }

        [Test]
        public void ReduceDropsSuppressedDiagonals() {
            Assert.AreEqual(OverlayMasks.N, OverlayMasks.Reduce(OverlayMasks.N | OverlayMasks.NE));
            Assert.AreEqual(OverlayMasks.NE, OverlayMasks.Reduce(OverlayMasks.NE));
            Assert.AreEqual(OverlayMasks.N | OverlayMasks.SE, OverlayMasks.Reduce(OverlayMasks.N | OverlayMasks.NE | OverlayMasks.SE));
        }

        [Test]
        public void Edge16RenderableMatchesComponents() {
            Random rng = new(5);
            for (int trial = 0; trial < 50; trial++) {
                int    sides = rng.Next(1 << 16) | 0, corners = rng.Next(16);
                bool   rs    = rng.Next(2) == 0,      rc      = rng.Next(2) == 0;
                bool[] r     = RenderableTables.Edge16(sides, corners, rs, rc);
                for (int m = 0; m < 256; m++) {
                    bool expect = true;
                    int e = ((m & OverlayMasks.N) != 0 ? 1 : 0) | ((m & OverlayMasks.E) != 0 ? 2 : 0) |
                            ((m & OverlayMasks.S) != 0 ? 4 : 0) | ((m & OverlayMasks.W) != 0 ? 8 : 0);
                    if (rs && e != 0 && ((sides >> e) & 1) == 0) {
                        expect = false;
                    }

                    if (rc) {
                        if ((m & OverlayMasks.NE) != 0 && (m & (OverlayMasks.N | OverlayMasks.E)) == 0 && (corners & 1) == 0) {
                            expect = false;
                        }

                        if ((m & OverlayMasks.SE) != 0 && (m & (OverlayMasks.S | OverlayMasks.E)) == 0 && (corners & 2) == 0) {
                            expect = false;
                        }

                        if ((m & OverlayMasks.SW) != 0 && (m & (OverlayMasks.S | OverlayMasks.W)) == 0 && (corners & 4) == 0) {
                            expect = false;
                        }

                        if ((m & OverlayMasks.NW) != 0 && (m & (OverlayMasks.N | OverlayMasks.W)) == 0 && (corners & 8) == 0) {
                            expect = false;
                        }
                    }

                    Assert.AreEqual(expect, r[m], $"mask {m}");
                }
            }
        }

        /// <remarks>
        /// Port from modern C# system.numerics.bitoperations
        /// </remarks>
        static int PopCount(uint value) {
            int count = 0;
            while (value != 0) {
                value &= value - 1;
                count++;
            }
            return count;
        }

        [Test]
        public void BlobRenderableChecksAfterReduction() {
            // only the empty slot and the single-side slots exist
            ulong avail = 0;
            for (int s = 0; s < OverlayMasks.BLOB_COUNT; s++) {
                if (!OverlayMasks.IsCornerSlot(s) &&
                    PopCount((uint)OverlayMasks.BlobSlotMask(s)) <= 1) {
                    avail |= 1UL << s;
                }
            }

            bool[] r = RenderableTables.Blob47(avail, true, false);
            Assert.IsTrue(r[OverlayMasks.N]);
            Assert.IsFalse(r[OverlayMasks.N | OverlayMasks.S]);
            // N+NE reduces to N, so it needs nothing more than N
            Assert.IsTrue(r[OverlayMasks.N | OverlayMasks.NE]);
            // corners are optional here
            Assert.IsTrue(r[OverlayMasks.NE]);
            bool[] strict = RenderableTables.Blob47(avail, true, true);
            Assert.IsFalse(strict[OverlayMasks.NE]);
        }

        // ---------------------------------------------------------------- rules
        static WFCRules Terrain3(bool diagonal) {
            WFCRulesBuilder b = new(3) { diagonalRules = diagonal };
            b.AllowCardinal(0, 1).AllowCardinal(1, 2); // water-sand, sand-grass; water never touches grass
            if (diagonal) {
                b.AllowDiagonal(0, 1).AllowDiagonal(1, 2);
            }

            return b.Build();
        }

        [Test]
        public void SupportIsSymmetric() {
            Random rng = new(11);
            for (int trial = 0; trial < 100; trial++) {
                int             n = rng.Next(2, 20);
                WFCRulesBuilder b = new(n) { diagonalRules = rng.Next(2) == 0 };
                for (int k = 0; k < n * 2; k++) {
                    b.AllowCardinal(rng.Next(n), rng.Next(n));
                    b.AllowDiagonal(rng.Next(n), rng.Next(n));
                }

                for (int k = 0; k < 5; k++) {
                    b.Restrict(rng.Next(n), (Direction)rng.Next(8), (ulong)rng.Next() & ((1UL << n) - 1), rng.Next(2) == 0);
                }

                Assert.IsNull(b.Build().Validate());
            }
        }

        [Test]
        public void DiagonalsAreIndependentOfCardinals() {
            WFCRules off = Terrain3(false);
            for (int d = 1; d < 8; d += 2) {
                for (int t = 0; t < 3; t++) {
                    Assert.AreEqual(off.FullMask, off.support[d * 3 + t], "diagonal rules off = unconstrained");
                }
            }

            WFCRules on = Terrain3(true);
            for (int d = 0; d < 8; d++) {
                Assert.AreEqual(3UL, on.support[d * 3 + 0] & 3UL); // water: itself + sand
                Assert.AreEqual(0UL, on.support[d * 3 + 0] & 4UL);              // never grass
            }

            // listing a pair only for cardinals does not open it diagonally
            WFCRulesBuilder b = new(2) { diagonalRules = true };
            b.AllowCardinal(0, 1);
            WFCRules r = b.Build();
            Assert.AreEqual(1UL, r.support[1 * 2 + 0]); // NE of tile 0: only tile 0
            Assert.AreEqual(3UL, r.support[0 * 2 + 0]); // N of tile 0: tiles 0 and 1
        }

        // ---------------------------------------------------------------- solving
        static void AssertAdjacency(WFCRules rules, byte[] layout, int w, int h) {
            int n = rules.count;
            for (int y = 0; y < h; y++) {
                for (int x = 0; x < w; x++) {
                    for (int d = 0; d < 8; d++) {
                        int nx = x + Dirs.Dx(d), ny = y + Dirs.Dy(d);
                        if (nx < 0 || ny < 0 || nx >= w || ny >= h) continue;
                        Assert.IsTrue(((rules.support[d * n + layout[y * w + x]] >> layout[ny * w + nx]) & 1) != 0, $"cell {x},{y} direction {(Direction)d}");
                    }
                }
            }
        }

        [Test]
        public void SolutionsRespectAdjacency() {
            foreach (bool diag in new[] { false, true }) {
                WFCRules       rules = Terrain3(diag);
                using WFCSolver s     = new(rules, 24, 17);
                for (ulong seed = 1; seed <= 20; seed++) {
                    Assert.AreEqual(WFCStatus.Success, s.Solve(seed), $"seed {seed}");
                    AssertAdjacency(rules, s.Layout, 24, 17);
                }
            }
        }

        [Test]
        public void SameSeedSameLayoutDifferentSeedDiffers() {
            WFCRules        rules = Terrain3(false);
            using WFCSolver a     = new(rules, 20, 20);
            using WFCSolver b     = new(rules, 20, 20);
            a.Solve(42);
            b.Solve(42);
            Assert.AreEqual(a.Layout, b.Layout);
            b.Solve(43);
            Assert.AreNotEqual(a.Layout, b.Layout);
        }

        [Test]
        public void ContradictoryStartingDomainsAreUnsatisfiable() {
            WFCRules        rules = Terrain3(false);
            using WFCSolver s     = new(rules, 4, 4);
            ulong[]         dom   = WFCDomains.Full(3, 4, 4);
            WFCDomains.Pin(dom, 4, 1, 1, 0); // water
            WFCDomains.Pin(dom, 4, 2, 1, 2); // grass next to it
            Assert.AreEqual(WFCStatus.Unsatisfiable, s.Solve(1, dom));
            Assert.AreEqual(WFCStatus.Success, s.Solve(1)); // the solver stays usable
        }

        [Test]
        public void PinnedCellsStayPinned() {
            WFCRules        rules = Terrain3(false);
            using WFCSolver s     = new(rules, 10, 10);
            ulong[]         dom   = WFCDomains.Full(3, 10, 10);
            WFCDomains.Pin(dom, 10, 5, 5, 2);
            Assert.AreEqual(WFCStatus.Success, s.Solve(3, dom));
            Assert.AreEqual(2, s.Layout[5 * 10 + 5]);
        }

        [Test]
        public void MustExistKeepsDoorsOffTheSouthEdgeAndOnRoads() {
            // 0 road, 1 door, 2 grass. A door needs a road directly south.
            WFCRulesBuilder b = new(3);
            b.AllowCardinal(0, 2).AllowCardinal(1, 2).AllowCardinal(0, 1);
            b.SetWeight(1, 3f);
            b.Restrict(1, Direction.S, 1UL << 0, true);
            WFCRules rules = b.Build();
            Assert.IsNull(rules.Validate());
            int             doors = 0;
            using WFCSolver s     = new(rules, 16, 12);
            for (ulong seed = 1; seed <= 30; seed++) {
                Assert.AreEqual(WFCStatus.Success, s.Solve(seed));
                for (int y = 0; y < 12; y++) {
                    for (int x = 0; x < 16; x++) {
                        if (s.Layout[y * 16 + x] != 1) continue;
                        doors++;
                        Assert.Greater(y, 0, "door on the south edge");
                        Assert.AreEqual(0, s.Layout[(y - 1) * 16 + x], "door without road to its south");
                    }
                }
            }

            Assert.Greater(doors, 0);
        }

        // ---------------------------------------------------------------- windows
        static bool[] RandomRenderable(Random rng) {
            bool[] r                           = new bool[256];
            for (int m = 1; m < 256; m++) {
                r[m] = rng.Next(3) != 0;
            }

            r[0] = true;
            return r;
        }

        [Test]
        public void WindowFeasibilityMatchesBruteForce() {
            Random rng = new(9);
            for (int trial = 0; trial < 5; trial++) {
                bool[]  r = RandomRenderable(rng);
                ulong[] f = WFCRulesBuilder.BuildFeasible(r);
                for (int may = 0; may < 256; may++) {
                    for (int must = 0; must < 256; must++) {
                        if ((must & ~may) != 0) {
                            continue;
                        }

                        bool expect = false;
                        for (int m = 0; m < 256 && !expect; m++) {
                            if ((m & must) == must && (m & ~may) == 0 && r[m]) {
                                expect = true;
                            }
                        }

                        int i = (must << 8) | may;
                        Assert.AreEqual(expect, ((f[i >> 6] >> (i & 63)) & 1UL) != 0, $"must {must} may {may}");
                    }
                }
            }
        }

        static void AssertWindowsHold(WFCRules rules, byte[] layout, int w, int h) {
            for (int k = 0; k < rules.windowCount; k++) {
                int     marker   = rules.windowMarker[k];
                ulong   targets  = rules.windowTargets[k];
                ulong[] feasible = rules.windowFeasible;
                for (int y = 0; y < h; y++) {
                    for (int x = 0; x < w; x++) {
                        if (((targets >> layout[y * w + x]) & 1) == 0) continue;

                        int mask = 0;
                        for (int d = 0; d < 8; d++) {
                            int nx = x + Dirs.Dx(d), ny = y + Dirs.Dy(d);
                            if (nx >= 0 && ny >= 0 && nx < w && ny < h && layout[ny * w + nx] == marker) {
                                mask |= 1 << d;
                            }
                        }

                        int i = (mask << 8) | mask; // a fully decided neighbourhood: must == may
                        Assert.IsTrue(((feasible[k * WFCRules.FEASIBLE_WORDS + (i >> 6)] >> (i & 63)) & 1UL) != 0, $"unrenderable mask {OverlayMasks.MaskName(mask)} at {x},{y}");
                    }
                }
            }
        }

        [Test]
        public void SolutionsAreRenderable() {
            // tile 0 = ground (overlay target), tile 1 = marker. Sides and corners are mandatory; the tileset lacks the two
            // opposite-sides pieces, the all-sides piece and the NW lone corner.
            WFCRulesBuilder b = new(2);
            b.AllowCardinal(0, 1);
            const int SIDES   = 0xFFFF & ~((1 << 5) | (1 << 10) | (1 << 15));
            const int CORNERS = 0x7;
            b.AddWindow(1, 1UL << 0, RenderableTables.Edge16(SIDES, CORNERS, true, true));
            WFCRules rules     = b.Build();
            int successes = 0, unconstrainedBad = 0;
            using (WFCSolver s = new(rules, 20, 20)) {
                for (ulong seed = 1; seed <= 40; seed++) {
                    if (s.Solve(seed) != WFCStatus.Success) continue;

                    successes++;
                    AssertWindowsHold(rules, s.Layout, 20, 20);
                }
            }

            Assert.Greater(successes, 30);
            using (WFCSolver s = new(rules, 20, 20)) {
                for (ulong seed = 1; seed <= 20; seed++) {
                    s.Solve(seed, default, default, 100, false);
                    WFCRulesBuilder probe = new WFCRulesBuilder(2).AllowCardinal(0, 1);
                    probe.AddWindow(1, 1UL << 0, RenderableTables.Edge16(SIDES, CORNERS, true, true));
                    try {
                        AssertWindowsHold(probe.Build(), s.Layout, 20, 20);
                    } catch (AssertionException) {
                        unconstrainedBad++;
                    }
                }
            }

            Assert.Greater(unconstrainedBad, 0, "the constraint should matter: without it unrenderable masks appear");
        }

        [Test]
        public void BlobWindowsHoldWithSeveralOverlays() {
            Random rng = new(77);
            for (int trial = 0; trial < 6; trial++) {
                const int       N = 4;
                WFCRulesBuilder b = new(N);
                for (int a = 0; a < N; a++) {
                    for (int c = a + 1; c < N; c++) {
                        b.AllowCardinal(a, c);
                    }
                }

                ulong avail = 1UL;
                for (int sl = 1; sl < 47; sl++) {
                    if (rng.Next(4) != 0) {
                        avail |= 1UL << sl;
                    }
                }

                b.AddWindow(1, (1UL << 0) | (1UL << 3),
                            RenderableTables.Blob47(avail, rng.Next(2) == 0, rng.Next(2) == 0));
                b.AddWindow(2, 1UL << 0, RenderableTables.Blob47(avail, true, true));
                WFCRules        rules = b.Build();
                using WFCSolver s     = new(rules, 14, 14);
                for (ulong seed = 1; seed <= 10; seed++) {
                    if (s.Solve(seed) != WFCStatus.Success) continue;
                    AssertWindowsHold(rules, s.Layout, 14, 14);
                }
            }
        }

        // Soundness: on tiny grids, the solver finds a solution whenever a brute-force search says one exists,
        // and never claims one when none exists.
        [Test]
        public void PropagationNeverPrunesValidSolutions() {
            Random rng = new(2024);
            for (int trial = 0; trial < 120; trial++) {
                int             n = rng.Next(2, 4);
                const int       W = 3;
                int             h = rng.Next(2, 4);
                WFCRulesBuilder b = new(n) { diagonalRules = rng.Next(2) == 0 };
                for (int k = 0; k < n; k++) {
                    b.AllowCardinal(rng.Next(n), rng.Next(n));
                    b.AllowDiagonal(rng.Next(n), rng.Next(n));
                }

                if (rng.Next(2) == 0) {
                    b.Restrict(rng.Next(n), (Direction)rng.Next(8), (ulong)rng.Next(1, 1 << n), rng.Next(2) == 0);
                }

                for (int k = 0; k < rng.Next(0, 3); k++) {
                    int   marker  = rng.Next(n);
                    ulong targets = (ulong)rng.Next(1, 1 << n) & ~(1UL << marker);
                    b.AddWindow(marker, targets, RandomRenderable(rng));
                }

                WFCRules rules = b.Build();

                int cells                             = W * h;
                int total                             = 1;
                for (int i = 0; i < cells; i++) {
                    total *= n;
                }

                bool   exists                         = false;
                byte[] lay                            = new byte[cells];
                for (int code = 0; code < total && !exists; code++) {
                    int c = code;
                    for (int i = 0; i < cells; i++) {
                        lay[i] =  (byte)(c % n);
                        c      /= n;
                    }

                    if (Valid(rules, lay, W, h)) {
                        exists = true;
                    }
                }

                using WFCSolver s  = new(rules, W, h);
                WFCStatus       st = s.Solve(1, default, default, 200);
                if (exists) {
                    Assert.AreEqual(WFCStatus.Success, st, $"trial {trial}: a solution exists");
                } else {
                    Assert.AreNotEqual(WFCStatus.Success, st, $"trial {trial}: no solution exists");
                }

                if (st == WFCStatus.Success) {
                    Assert.IsTrue(Valid(rules, s.Layout, W, h), $"trial {trial}: solver output invalid");
                }
            }
        }

        static bool Valid(WFCRules rules, byte[] lay, int w, int h) {
            int n = rules.count;
            for (int y = 0; y < h; y++) {
                for (int x = 0; x < w; x++) {
                    int t = lay[y * w + x];
                    for (int d = 0; d < 8; d++) {
                        int  nx     = x + Dirs.Dx(d), ny = y + Dirs.Dy(d);
                        bool inside = nx >= 0 && ny >= 0 && nx < w && ny < h;
                        if (!inside) {
                            if (((rules.mustExist[d] >> t) & 1) != 0) {
                                return false;
                            }

                            continue;
                        }

                        if (((rules.support[d * n + t] >> lay[ny * w + nx]) & 1) == 0) {
                            return false;
                        }
                    }

                    for (int k = 0; k < rules.windowCount; k++) {
                        if (((rules.windowTargets[k] >> t) & 1) == 0) {
                            continue;
                        }

                        int mask = 0;
                        for (int d = 0; d < 8; d++) {
                            int nx = x + Dirs.Dx(d), ny = y + Dirs.Dy(d);
                            if (nx >= 0 && ny >= 0 && nx < w && ny < h && lay[ny * w + nx] == rules.windowMarker[k]) {
                                mask |= 1 << d;
                            }
                        }

                        int i = (mask << 8) | mask;
                        if (((rules.windowFeasible[k * WFCRules.FEASIBLE_WORDS + (i >> 6)] >> (i & 63)) & 1UL) == 0) {
                            return false;
                        }
                    }
                }
            }

            return true;
        }

        // ---------------------------------------------------------------- weights
        [Test]
        public void CellWeightsBiasTheResult() {
            WFCRulesBuilder b = new(2);
            b.AllowCardinal(0, 1);
            WFCRules  rules = b.Build();
            const int W     = 30;
            const int H     = 30;
            float[]   cw    = new float[W * H * 2];
            for (int i = 0; i < W * H; i++) {
                cw[i * 2]     = 1f;
                cw[i * 2 + 1] = i % W < W / 2 ? 0.0001f : 1000f;
            }

            using WFCSolver s = new(rules, W, H);
            Assert.AreEqual(WFCStatus.Success, s.Solve(5, default, cw));
            int left = 0, right = 0;
            for (int y = 0; y < H; y++) {
                for (int x = 0; x < W; x++) {
                    if (s.Layout[y * W + x] != 1) continue;
                    if (x < W / 2) {
                        left++;
                    } else {
                        right++;
                    }
                }
            }

            Assert.Greater(right, left * 3);
        }

        [Test]
        public void BiomeWeightsAreDeterministic() {
            float[] a = BiomeWeights.Build(12, 9, 3, new[] { 1f, 2f }, new[] { 0.2f, 0.8f }, 0.7f);
            float[] b = BiomeWeights.Build(12, 9, 3, new[] { 1f, 2f }, new[] { 0.2f, 0.8f }, 0.7f);
            Assert.AreEqual(a, b);
            Assert.AreEqual(12 * 9 * 2, a.Length);
        }
